{
  "predictors": [
    {
      "name": "Earnings Stability Surprise",
      "construction": "Calculate the standard deviation of quarterly earnings over the past five years and compare it to analyst forecast dispersion in the last quarter.",
      "rationale": "Stocks with unexpectedly stable earnings compared to analyst forecasts might be undervalued due to lower perceived risk.",
      "higher_returns_for": "Stocks with lower earnings stability surprise."
    },
    {
      "name": "CEO Media Sentiment",
      "construction": "Analyze the tone of major financial news articles about the CEO over the past year using a sentiment analysis algorithm.",
      "rationale": "Positive media sentiment about leadership may indicate effective management and future performance improvements.",
      "higher_returns_for": "Stocks with higher CEO media sentiment."
    },
    {
      "name": "R&D Impact Score",
      "construction": "Divide R&D expenses by the change in sales over the past year and adjust for industry averages.",
      "rationale": "Efficient R&D spending leading to higher sales growth could signal superior future returns.",
      "higher_returns_for": "Stocks with higher R&D impact scores."
    },
    {
      "name": "Board Diversity Index",
      "construction": "Create an index based on the diversity (gender, age, ethnicity) of the board relative to industry norms.",
      "rationale": "Greater diversity in board composition may lead to more innovative solutions and better governance.",
      "higher_returns_for": "Stocks with higher board diversity index."
    },
    {
      "name": "Customer Satisfaction Growth",
      "construction": "Measure the year-over-year change in customer satisfaction scores from third-party surveys.",
      "rationale": "Improvements in customer satisfaction can lead to increased customer loyalty and sales.",
      "higher_returns_for": "Stocks with higher customer satisfaction growth."
    },
    {
      "name": "Employee Productivity Change",
      "construction": "Calculate the percentage change in revenue per employee over the past year.",
      "rationale": "Increasing employee productivity might indicate effective use of human capital and cost control.",
      "higher_returns_for": "Stocks with higher employee productivity change."
    },
    {
      "name": "Environmental Compliance Efficiency",
      "construction": "Ratio of environmental compliance costs to total fines and penalties over the past year.",
      "rationale": "Efficient handling of environmental issues suggests lower future regulatory risk.",
      "higher_returns_for": "Stocks with lower environmental compliance efficiency."
    },
    {
      "name": "Supply Chain Resilience",
      "construction": "Assess the number and diversity of suppliers and compare this to the industry average.",
      "rationale": "A resilient supply chain can mitigate risks associated with supplier disruptions.",
      "higher_returns_for": "Stocks with higher supply chain resilience."
    },
    {
      "name": "Innovation Mentions",
      "construction": "Number of times the company is mentioned in patent filings and innovation-focused conferences over the past year.",
      "rationale": "Frequent mentions in innovation contexts may indicate a strong pipeline of new products.",
      "higher_returns_for": "Stocks with higher innovation mentions."
    },
    {
      "name": "Tax Optimization Index",
      "construction": "Effective tax rate compared to the average industry tax rate over the past three years.",
      "rationale": "A lower effective tax rate through legal optimization can enhance net profitability.",
      "higher_returns_for": "Stocks with lower tax optimization index."
    }
  ]
}
